css:
.questionLink {
  width: 100%;
  height: auto;
  font-size: min(16px, 3vw);
  text-align: center;
  color: #3f3a3b;
}

.questionLink .progress {
  width: 90%;
  height: auto;
  margin: 0 auto;
  display: flex;
  justify-content: center;
  align-items: center;
  column-gap: 2em;
}

.questionLink .progress .progress__item {
  width: 3em;
  height: 3em !important;
  background: transparent;
  border-radius: 1.5em;
  display: flex;
  justify-content: center;
  align-items: center;
  color: #999;
  font-size: 1em;
  font-weight: bold;
  position: relative;
}

.questionLink .progress .progress__item:before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 1.5em;
  background: #eee;
  z-index: 1;
}

.questionLink .progress .progress__item span {
  position: relative;
  z-index: 2;
}

.questionLink .progress .progress__item.is-active {
  color: #fff;
}

.questionLink .progress .progress__item.is-active:before {
  background: #524646;
}

.questionLink .progress .progress__item:after {
  content: '';
  width: 5em;
  height: auto;
  display: block;
  border-top: 2px solid #eee;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 0;
}

.questionLink .progress .progress__item:first-of-type:after {
  width: 3em;
  transform: translate(0, -50%);
}

.questionLink .progress .progress__item:last-of-type:after {
  width: 3em;
  left: initial;
  right: 50%;
  transform: translate(0, -50%);
}

.questionLink .head {
  margin-top: 1.5em;
}

.questionLink .head .head__text {
  font-size: 1.2em;
  font-weight: 600;
  line-height: 1.5;
}

.questionLink .head .head__note {
  font-size: 0.7em;
  font-weight: normal;
  margin: 0.5em 0;
}

.questionLink .video {
  margin-top: 1.5em;
}

.questionLink .video .video__movie {
  width: 100%;
  height: auto;
}

.questionLink .video .video__time {
  font-size: 0.9em;
  line-height: 1;
  margin-top: 0.5em;
}

 .widget-container {
  font-size: clamp(14px, calc(0.63vw + 12px), 16px);
  width: min(100%, 750px);
  margin-inline: auto;
  box-sizing: border-box;
}

 .widget-container * {
  box-sizing: border-box;
}

 .video-first-view {
  position: relative;
  font-size: 16px;
  max-width: 980px;
  margin-left: auto;
  margin-right: auto;
}

 .video-first-view img,
 .video-first-view video,
 .video-first-view iframe {
  max-width: unset;
  width: 100%;
}

 .video-first-view-frame {
  position: relative;
  width: 100%;
  aspect-ratio: 9/16;
}

 .video-first-view-frame img,
 .video-first-view-frame video,
 .video-first-view-frame iframe {
  width: 100%;
  height: 100% !important;
  object-fit: cover;
}

 .video-first-view-sound {
  position: absolute;
  right: 0.75em;
  bottom: 3.5em;
  z-index: 5;
  display: flex;
  align-items: center;
  background-color: rgba(0, 0, 0, 0.6);
  color: #fff;
  font-size: 0.875em;
  line-height: 1;
  padding: 0.7em 1.2em;
  border-radius: 2em;
  cursor: pointer;
  user-select: none;
}

 .video-first-view-sound::before {
  content: '';
  width: 1em;
  height: 1em;
  margin-right: 0.5em;
  background-color: currentColor;
  clip-path: polygon(0% 30%, 30% 30%, 60% 0%, 60% 100%, 30% 70%, 0% 70%);
}

 .video-first-view-sound .label-on {
  display: none;
}

 .video-first-view.is-unmuted .video-first-view-sound .label-off {
  display: none;
}

 .video-first-view.is-unmuted .video-first-view-sound .label-on {
  display: inline;
}

 .video-first-view-timer {
  display: flex;
  align-items: center;
  font-size: 0.875em;
  line-height: 1;
  padding: 0.7em 1em;
  border-radius: 2em;
  pointer-events: none;
  width: fit-content;
  margin: 1em auto;
}

 .video-first-view-timer span::after {
  content: attr(data-unit);
}

 .video-first-view-next {
  text-align: center;
  width: fit-content;
  margin: 0.75em auto;
}

 .video-first-view-next button {
  appearance: none;
  border: none;
  font-family: inherit;
  background-color: #333;
  color: #fff;
  font-size: 0.875em;
  line-height: 1;
  padding: 0.9em 2em;
  cursor: pointer;
}

 .video-first-view-contents {
  overflow: hidden;
  transition: 0.5s;
}

 .video-first-view .is-ended {
  z-index: 105;
}

 .video-first-view.is-ended {
  z-index: 110;
}

 .video-first-view.is-ended .video-first-view-next {
  display: none;
}

 .video-first-view.is-ended[data-hidden="1"] .video-first-view-movie {
  animation: fadeOut 1s ease 0s forwards;
  overflow: hidden;
}

 .video-first-view.is-ended .video-first-view-contents {
  position: relative;
  animation: fadeIn 1s ease 0.5s forwards;
  max-height: 100vh !important;
  z-index: 99;
}

 .is-hidden {
  display: none !important;
}

@keyframes fadeIn {
  0% {
    opacity: 0;
    max-height: 0;
  }

  100% {
    max-height: 100vh;
    opacity: 1;
  }
}

@keyframes fadeOut {
  0% {
    opacity: 1;
    max-height: 1000vh;
  }

  100% {
    max-height: 0;
    opacity: 0;
  }
}

@keyframes popUpFadeIn {
  0% {
    opacity: 0;
    max-height: 0;
  }

  25% {
    opacity: 0;
    max-height: 100vh;
  }

  100% {
    opacity: 1;
  }
}

.tabContent__area {
  width: 100%;
  height: auto;
  position: relative;
  font-size: min(16px, 3vw);
}

.tabContent__area .tabContent__item {
  display: none;
  padding-bottom: 2em;
}

.tabContent__area .tabContent__item.is-active {
  display: block;
}

.tabContent__area .tabContent__item img {
  width: 100%;
  height: auto;
  vertical-align: bottom;
}

.tabContent__area .tabContent__switch {
  position: fixed;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 100%;
  max-width: 600px;
  height: auto;
  display: flex;
  box-shadow: 0 0 15px rgba(0, 0, 0, 0.3);
}

.tabContent__area .tabContent__switch .btn {
  width: stretch;
  height: auto;
  border: none;
  background: #fff;
  padding: calc(0.5em + 2px) 0 0.5em;
  text-align: center;
  border-bottom: 2px solid #34908B;
  color: #333;
  font-size: 1em;
  cursor: pointer;
}

.tabContent__area .tabContent__switch .btn+.btn {
  border-left: 2px solid #eee;
}

.tabContent__area .tabContent__switch .btn.is-active {
  background: #34908B;
  color: #fff;
}

.mapSearch__container {
  font-size: min(16px, 3vw);
}

.searchButton {
  background: #9B8EC7;
  color: #fff;
  border: none;
  padding: 1em 2em;
  margin: 0 auto;
  display: block;
  border-radius: 1em;
  cursor: pointer;
  font-weight: bold;
  font-size: 1.2em;
  margin-bottom: 1em;
  width: 100%;
  max-width: 400px;
  box-shadow: 0 4px 0 #7a709d;
}

.mapList {
  width: 100%;
  max-width: 400px;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  flex-wrap: wrap;
  column-gap: 0.5em;
  row-gap: 0.5em;
  margin: 1em auto 0;
}

.storeLink__item {
  width: 40%;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  min-height: 60px;
  padding: 1em;
  border: 2px solid #F2EAE0;
  text-decoration: none;
  color: #333;
  border-radius: 1em;
  background: #fbf9f7;
}

.storeLink__item.item {
  color: #666;
  font-size: 0.9em;
}

.mapName {
  display: block;
  font-weight: bold;
  text-decoration: underline;
  color: #6d8f96;
  margin-bottom: 5px;
}

.distance {
  font-size: 0.85em;
  color: #6d8f96;
  text-decoration: underline;
}

.error {
  color: #8f4f4f;
  font-size: 0.9em;
  margin-top: 1em;
}

.nav__area {
  width: 100%;
  display: flex;
  justify-content: center;
}

.nav__area a {
  width: 45%;
  height: auto;
  display: block;
  color: #fff;
  background-color: #44A194;
  text-align: center;
  text-decoration: none;
  font-weight: bold;
  font-size: 1.1em;
  padding: 0.4em 0;
  border-radius: 15vw;
  cursor: pointer;
  transition: background-color 0.2s;
  margin: 1em auto 0;
}

.nav__area a:hover {
  background-color: #2e6d65;
}

@media screen and (max-width:600px) {
  .nav__area {
    flex-direction: column;
  }

  .nav__area a {
    width: 80%;
  }
}

.tabs__trigger {
  padding: 10px 20px;
  cursor: pointer;
  background: #efefef;
  border: none;
}

.tabs__trigger.is-active {
  background: #EC8F8D;
  color: #fff;
}

.tab__content {
  display: none;
  padding: 20px;
  border: 1px solid #eee;
}

.tab__content.is-active {
  display: block;
}

.widget-container {
  font-size: 16px;
  width: min(100%, 1280px);
  margin-inline: auto;
  box-sizing: border-box;
}

.widget-container * {
  box-sizing: border-box;
}

.style-carousel {
  overflow: hidden;
}


.style-carousel-slider {
  padding: 1.5em 0 0;
  overflow: visible;
  position: relative;
}

.style-carousel-slider.swiper {
  overflow: hidden;
}

.style-carousel-slider .swiper-wrapper {
  height: auto;
}

.style-carousel-slide {
  padding: 0;
}

.style-carousel-slide-name {
  display: flex;
  align-items: center;
  gap: 0.6em;
  margin: 0 0 1em;
  line-height: 1;
  padding: 0 0.25em;
}

.style-carousel-slide-name::after {
  content: '';
  flex: 1;
  height: 1px;
  background: #333;
  translate: -7px 0;
}

.style-carousel-slide-name span {
  font-size: 1.2em;
  font-weight: 700;
  letter-spacing: 0.1em;
}

.style-carousel-slide-body {
  display: flex;
  gap: 0.5em;
}

.style-carousel-slide-image {
  flex: 1;
  overflow: hidden;
}

.style-carousel-slide-image img {
  width: 100%;
  height: 100% !important;
  display: block;
  object-fit: cover;
}

.style-carousel-slide-catch {
  writing-mode: vertical-rl;
  font-size: 0.875em;
  color: #555;
  font-weight: 500;
  line-height: 1.5;
  letter-spacing: 0.2em;
  white-space: nowrap;
  padding: 0.1em 0;
  padding-top: 45px;
  position: relative;
  translate: 0 -25px;
}

.style-carousel-slide-catch::before {
  content: '';
  display: block;
  width: 1px;
  height: 35px;
  background: #333;
  position: absolute;
  top: 0;
  left: 50%;
  translate: -50% 0;
}

.style-carousel-slide-desc {
  color: #555;
  line-height: 1.8;
  margin: 0.8em 0 0;
  padding: 0 0.25em;
}

.style-carousel-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 1.2em;
  padding: 1em 0.25em;
}

.style-carousel-pagination {
  display: flex;
  gap: 0.5em;
  justify-content: flex-end;
}

.style-carousel-pagination .swiper-pagination-bullet {
  width: 8px;
  height: 8px;
  background: #ccc;
  border-radius: 50%;
  opacity: 1;
  cursor: pointer;
  transition: background 0.3s;
}

.style-carousel-pagination .swiper-pagination-bullet-active {
  background: #3a3028;
}

.style-carousel-arrows {
  display: flex;
  gap: 0.5em;
}

.style-carousel-prev,
.style-carousel-next {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid #bbb;
  cursor: pointer;
  position: relative;
  transition: opacity 0.3s;
  flex-shrink: 0;
}

.style-carousel-prev:hover,
.style-carousel-next:hover {
  opacity: 0.6;
}

.style-carousel-prev::after,
.style-carousel-next::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 8px;
  height: 8px;
  border-top: 2px solid #bbb;
  border-right: 2px solid #bbb;
}

.style-carousel-prev::after {
  transform: translate(-30%, -50%) rotate(-135deg);
}

.style-carousel-next::after {
  transform: translate(-70%, -50%) rotate(45deg);
}

.style-carousel-bg-text {
  color: #eee;
  font-size: clamp(36px, calc(13.75vw + -8px), 80px);
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.02em;
  white-space: nowrap;
  overflow: hidden;
  padding: 0 0 0.3em;
  margin: -0.2em 0 0;
}

.style-carousel-slider .swiper-pagination {
  position: static;
}

.EDITABLE .swiper {
  position: relative;
  overflow: unset;
}

.EDITABLE .swiper::after {
  content: "※←横スライドでアイテムを確認してください(このテキストは本番では非表示になります)→";
  width: 100%;
  height: 50px;
  text-align: center;
  line-height: 1;
  font-size: .8em;
  position: absolute;
  bottom: -2em;
  color: #656565;
}

.EDITABLE .swiper-wrapper {
  overflow-x: scroll;
  scroll-snap-type: x mandatory;
}

.EDITABLE .swiper-slide {
  width: 80%;
  margin: 0 10px;
  scroll-snap-align: start;
}

 .moviePopup__btn {
  width: 200px;
  height: auto;
  border: none;
  background: none;
  cursor: pointer;
  opacity: 1;
  transition: opacity 0.2s;
  position: fixed;
  bottom: 10px;
  right: 10px;
  z-index: 999;
}

 .moviePopup__btn img {
  width: 100%;
  height: auto;
}

 .moviePopup__btn:hover {
  opacity: 0.8;
}

 .widget-popup {
  display: none;
  position: relative;
  background-color: #fff;
  border-radius: 10px;
  width: 400px;
  max-width: 100%;
  padding: 0;
  text-align: center;
  overflow: hidden;
  box-sizing: border-box;
}

 .widget-popup.active {
  display: block;
  position: fixed;
  bottom: 10px;
  right: 10px;
  z-index: 9999;
}

 .widget-popup .close {
  width: 50px;
  height: 50px;
  position: absolute;
  top: 0;
  right: 0;
  cursor: pointer;
  color: #fff;
  font-size: 50px;
  display: flex;
  justify-content: center;
  align-items: center;
}

 .widget-popup video {
  width: 100%;
  height: auto;
  margin: 0 !important;
  vertical-align: middle;
}

 .js-display-none {
  border: 1px dashed #000;
  border-radius: 5px;
  text-align: center;
  padding: 1em;
}

.changeImage__area {
  width: 100%;
  height: auto;
  font-size: min(3vw, 16px);
}

.changeImage--text {
  font-size: 1.2em;
  text-align: center;
}

.changeImage__box {
  width: 100%;
  height: auto;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  column-gap: 0.5em;
}

.changeImage__box img {
  width: 100%;
  height: auto;
}

.changeImage__box input {
  display: none;
}

.changeImage__box label {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 1/1;
  perspective: 1000px;
  cursor: pointer;
  position: relative;
}

.selectFlont__item,
.selectBack__item {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  backface-visibility: hidden;
  transition: transform 0.6s ease;
}

.selectFlont__item {
  transform: rotateY(0deg);
  z-index: 2;
}

.selectBack__item {
  transform: rotateY(180deg);
  z-index: 1;
}

.changeImage__box label {
  position: relative;
}

.changeImage__box input:checked+label .selectFlont__item {
  transform: rotateY(-180deg);
}

.changeImage__box input:checked+label .selectBack__item {
  transform: rotateY(0deg);
}

.changeImage__area .linkBtn {
  width: 100%;
  height: auto;
  display: block;
  margin: 1em auto 0;
  opacity: 1;
  transition: opacity 0.2s;
}

.changeImage__area .linkBtn img {
  width: 100%;
  height: auto;
}

.changeImage__area .linkBtn:hover {
  opacity: 0.8;
}

 .widget-container {
  font-size: 16px;
  max-width: 1140px;
  margin-inline: auto;
  line-height: 1.35;
  box-sizing: border-box;
}

@media (max-width: 500px) {
   .widget-container {
    font-size: 3.3vw;
  }
}

 .widget-container * {
  box-sizing: border-box;
}

 .modal-contents-wrapper.column-2 {
  display: grid;
  grid-template-columns: calc(50% - 1em) calc(50% - 1em);
  gap: 2em;
}

@media (max-width: 500px) {
   .modal-contents-wrapper.sp-column-1 {
    grid-template-columns: 100%;
    gap: 1em;
  }
}

 .modal-contents-item {
  background-color: #fff;
  padding: 1.5em;
  border-radius: 5px;
}

 .modal-contents-item .image {
  border-radius: 5px;
  overflow: clip;
}

 .modal-contents-item .image img {
  width: 100%;
  height: auto;
}

 .modal-contents-item .button {
  margin-top: 1em;
}

 .modal-contents-item .button a,.modal-contents-item .button button {
  text-align: center;
  width: 100%;
  background-color: #8891c8;
  color: #fff;
  border-radius: 100px;
  border: solid 1px #7382bd;
  padding: 1em 0;
  line-height: 1;
  transition: filter 0.3s;
}

 .modal-contents-item .button button:hover {
  filter: brightness(0.8);
}
 dialog {
  container-type: inline-size;
  border: none !important;
  background: rgba(0, 0, 0, 0.5);
  width: 100%;
  height: 100%;
  position: fixed;
  place-content: center;
  opacity: 0;
  max-width: unset;
  max-height: unset;
  padding: 0;
}

 dialog .scroll-container {
  background-color: #fff;
  color: #000;
  border-radius: 5px;
  padding: 3% 2.5%;
  max-height: 80vh;
  overflow-y: scroll;
}

 dialog .scroll-container>*+* {
  margin-top: 1.5em;
}

 dialog .scroll-container .title {
  font-size: 1.35em;
  font-weight: 600;
  text-align: center;
  color: #325b9e;
}

 dialog .inner {
  width: min(1000px, 90%);
  margin-inline: auto;
  position: relative;
}

 dialog .content {
  display: grid;
  grid-template-columns: calc(45% - 1em) calc(55% - 1em);
  gap: 2em;
}

 dialog .content .image {
  grid-area: image;
}

 dialog .content .buttons {
  grid-area: buttons;
  padding-bottom: 1em;
}

 dialog .content .data>*+* {
  margin-top: 1em;
}

 dialog .content .data dl dt {
  width: fit-content;
  background-color: #8a8cc3;
  color: #fff;
  padding: 0.25em 1em;
  border-radius: 100px;
  font-size: 0.875em;
}

 dialog .content .data dl dd {
  margin-top: 0.5em;
  font-size: 0.875em;
}

 dialog .content .googlemap {
  padding-bottom: 65%;
  position: relative;
}

 dialog .content .googlemap iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

 dialog .close {
  width: 2.5em;
  aspect-ratio: 1;
  color: #8a8cc3;
  background: transparent;
  position: absolute;
  top: 1em;
  right: 1em;
  margin-top: 0;
}

 dialog .close button {
  width: 100%;
  height: 100%;
  position: relative;
  background-color: #fff;
  border: solid 3px currentColor;
  border-radius: 50%;
}

 dialog .close button::before {
  content: "";
  width: 100%;
  aspect-ratio: 1;
  display: block;
  background: currentColor;
  clip-path: polygon(10% 0, 0 10%, 40% 50%, 0 90%, 10% 100%, 50% 60%, 90% 100%, 100% 90%, 60% 50%, 100% 10%, 90% 0, 50% 40%);
}

 .is-show dialog {
  display: grid;
  animation: fadeInModal 0.5s forwards;
}

 .is-close dialog {
  animation: fadeOutModal 0.5s forwards !important;
}

 .set-shadow {
  box-shadow: 0px 2px 8px 5px rgba(0, 0, 0, 0.15);
}

 button {
  cursor: pointer;
  display: block;
  border: none;
  outline: none;
  background: none;
}

 dl,
 dd {
  margin: 0;
}

a {
	display: block;
	text-decoration: none;
}

@keyframes fadeInModal {
  0% {
    opacity: 0;
  }

  100% {
    opacity: 1;
  }
}

@keyframes fadeOutModal {
  0% {
    opacity: 1;
  }

  100% {
    opacity: 0;
  }
}

 .EDITABLE .modal-contents-item dialog {
  display: grid;
  opacity: 1;
  position: relative;
  height: fit-content;
  margin-top: 1em;
}

 .refine-search,
 .refine-search-result {
  font-size: clamp(12.8px, 2.5vw, 16px);
  max-width: min(100%, 1000px);
  margin-inline: auto;
}

 .refine-search * {
  box-sizing: border-box;
}

 .refine-search+.refine-search-result {
  margin-top: 2em;
}

 .refine-search-title,
