  z-index: -1;
  pointer-events: none;
}

.story-slide-item.is-active {
  z-index: 1;
  opacity: 1;
  pointer-events: auto;
}

.story-slide-item.is-next,
.story-slide-item.is-prev {
  z-index: 0;
  opacity: 1;
}

.story-slide-item.is-past {
  z-index: 2;
  opacity: 1;
  animation: slideFadeOut 0.5s linear forwards;
}

.story-slide-item picture,
.story-slide-item img {
  display: block;
  width: 100%;
  height: 100% !important;
  object-fit: cover;
}

.story-slide-next,
.story-slide-prev {
  position: absolute;
  width: 50%;
  height: 100%;
  top: 0;
  z-index: 100;
  pointer-events: auto;
  cursor: pointer;
  transition: opacity 0.25s ease-in-out;
}

.story-slide-next::before,
.story-slide-prev::before,
.story-slide-next::after,
.story-slide-prev::after {
  content: "";
  width: 1.75em;
  aspect-ratio: 1;
  border-radius: 50%;
  background: #0286ff;
  position: absolute;
  top: 50%;
  translate: 0 -50%;
  left: 10px;
  z-index: 101;
}

.story-slide-next::after,
.story-slide-prev::after {
  border-radius: 0;
  width: 0.5em;
  background: none;
  border-top: 2px solid #fff;
  border-right: 2px solid #fff;
  transform: rotate(45deg);
}

.story-slide-next {
  right: 0;
}

.story-slide-next::before,
.story-slide-next::after {
  left: unset;
  right: 10px;
}

.story-slide-next::after {
  right: calc(10px + 0.65em);
}

.story-slide-prev {
  left: 0;
}

.story-slide-prev::after {
  left: calc(10px + 0.65em);
  transform: rotate(225deg);
}

.story-slide-indicator {
  position: absolute;
  bottom: 0.5em;
  right: 0.5em;
  z-index: 100;
  pointer-events: none;
}

.story-slide-indicator::before,
.story-slide-indicator::after {
  content: "";
  width: 2em;
  aspect-ratio: 1;
  display: block;
}

.story-slide-indicator::before {
  clip-path: polygon(90% 50%, 20% 100%, 20% 0);
  background-color: #000;
  width: 0.75em;
  position: absolute;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
}

.story-slide-indicator::after {
  content: "";
  background-color: #fff;
  border-radius: 50%;
}

.story-slide.is-pause .story-slide-indicator::before {
  clip-path: inset(20% 20% 20% 20%);
}

.story-slide.is-pause .story-slide-next,
.story-slide.is-pause .story-slide-prev {
  opacity: 0.5;
