}

.grid__area {
  display: grid;
  grid-template:
    'area1 area1 area2 area2 area2 area2 area2' auto
    'area1 area1 area3 area3 area3 area3 area3' auto
    'area1 area1    .    .     .     .     .    ' auto
    'area4 area5 area5 area5 area5 area6 area6' auto
    'area7 area8 area8 area8 area8 area8 area8' auto
    'area9 area9 area9 area9 area9 area9 area9' auto
