.introductItem__headBox {
  grid-area: area2;
}

.introductItem__pointBox {
  grid-area: area3;
}

.introductItem__statusBox {
  grid-area: area4;
}

.introductItem__detailBox {
  grid-area: area5;
}

.introductItem__otherInfoBox {
  grid-area: area6;
}

.introductItem__boardBox {
  grid-area: area7;
}

.introductItem__linkBox {
  grid-area: area8;
}

.introductItem__cautionBox {
  grid-area: area9;
}

.introductItem__headBox {
