}

.introductItem__boardBox .introductItem__boardContent .introductItem__boardContentInner {
  background-color: #000;
  padding: 0.5em;
}

.introductItem__boardBox .introductItem__boardContent .introductItem__boardContentInner .boardContent {
  color: #fff;
