  color: #fff;
}

.introductItem__cautionBox .cautionLists li+li {
  margin-top: 0.25em;
}



/* モーダル //////////////////////////*/
.select-modal {
  background-color: #fff;
  transition: opacity 0.3s, visibility 0.3s;
  position: relative;
}

.select-modal-wrap {
  transition: opacity 0.3s, visibility 0.3s;
  position: fixed;
  width: min(750px, 90%);
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  z-index: 1000;
}

.select-modal__title {
  width: 100%;
  text-align: center;
  font-size: 1.25em;
  font-weight: 600;
  color: #fff;
  background-color: #d02112;
  padding: 0.5em 1em;
}

.select-modal__inner {
  padding: 1em;
}

.select-modal__inner>*+* {
  margin-top: 0.5em;
}

.select-modal__item input {
  display: none;
}

.select-modal__item input+label {
  display: block;
  background-color: #fff;
  padding: 0.5em 1em;
  border-radius: 99px;
  cursor: pointer;
  border: solid 1px #ddd;
  text-align: center;
  font-size: 1.125em;
}

.select-modal__item input:checked+label {
  background-color: #ffc6c1;
}

.select-modal__backBtn {
  display: block;
  text-align: center;
  padding-bottom: 1em;
  color: #666;
  cursor: pointer;
  font-size: 0.85em;
}

.modal-overlayer {
  position: fixed;
  width: 100%;
  height: 100%;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.5);
  z-index: 999;
  opacity: 0;
  transition: opacity 0.3s;
}

.modal-close {
  position: absolute;
  top: 0.75em;
  right: 1em;
  cursor: pointer;
  z-index: 10001;
}

.modal-close::before {
  content: "×";
  display: inline-block;
  line-height: 1;
  font-size: 1.5em;
}


/* 状態管理 //////////////////////////*/

.is-hide {
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
  max-height: 0;
  overflow: hidden;
  margin: 0;
}

.is-fadeIn {
  opacity: 1;
  pointer-events: auto;
  visibility: visible;
  max-height: 100vh;
  overflow: visible;
}

.is-fadeOut {
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
  max-height: 0;
  overflow: hidden;
}

._clGreen {
  color: #A4C520;
}

._clOrange {
  color: #ff7e21;
}

._bold {
  color: #C7243A;
}

._bg {
  background-color: #FEF7D5;
}

/* デフォルトスタイル //////////////////////////*/

* {
  box-sizing: border-box;
}

button {
  border: none;
  background-color: transparent;
  cursor: pointer;
  padding: 0;
  margin: 0;
  outline: none;
  font-size: inherit;
}

img {
  width: 100%;
  height: auto;
  vertical-align: middle;
}

p {
  margin: 0;
}

ul,
dl,
dd {
  padding-left: 0;
  margin: 0;
  list-style: none;
}


/* ローディング //////////////////////////*/
.search-result__loading.is-hide {
  display: none;
}

.loader {
  text-align: center;
  position: relative;
  z-index: 10000;
  pointer-events: none;
}

.loader:after {
  content: '';
  display: block;
  width: 40px;
  height: 40px;
  margin-inline: auto;
  border: 4px solid #f3f3f3;
  border-top: 4px solid #d02112;
  border-radius: 50%;
  animation: spin 1s linear infinite;
  z-index: 1000;
}


/* 固定アイテム //////////////////////////*/

.fixed-item {
  margin: 3.5em 0;
  position: relative;
  padding: 3.5em 0;
  transition: all 0.3s ease;
}

.fixed-item::before {
  content: "";
  display: block;
  width: 100vw;
  background-color: #f5af5e;
  position: absolute;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
  height: 100%;
  z-index: 0;
}

.fixed-item.is-hide {
  padding: 0;
  margin: 0;
}

.strong-text {
  position: relative;
  z-index: 1;
  margin-bottom: 1em;
  font-size: 2.5em;
  font-weight: 800;
  color: #fff;
  text-align: center;
  text-shadow: 3px 3px 2px #eb5203, -1px 1px 0 #eb5203, 1px -1px 0 #eb5203, -1px -1px 0 #eb5203;
}

.fixed-item .search-result__itemTitle {
  text-align: center;
  padding-left: 0;
}

.fixed-item .search-result__itemTitle::before {
  display: none !important;
}


/* ホップアップ //////////////////////////*/

.init-popup {
  opacity: 1;
  transition: opacity 0.3s ease;
}

.init-popup.is-close {
  opacity: 0;
  pointer-events: none;
}

.init-popup__wrap {
  width: min(850px, 96%);
  margin-inline: auto;
  background-color: #fff;
  position: relative;
  z-index: 100;
  position: fixed;
  top: 50%;
  left: 50%;
  translate: -50% -50%;
  border: solid 1px #ddd;
}

.init-popup::before {
  content: "";
  display: block;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.8);
  position: fixed;
  top: 0;
  left: 0;
  z-index: 99;
}

.init-popup__title {
  background-color: #ccebff;
  padding: 1.25em min(10.625em, 22%) 1.25em 1.25em;
  position: relative;
  text-align: center;
}

.title-row .text {
  font-size: clamp(12px, 3.6vw, 32px);
  font-weight: 600;
}

.title-row .caption {
  font-size: clamp(10px, 2.4vw, 14px);
  color: #666;
}

.init-popup__title .image-row {
  position: absolute;
  width: min(10.625em, 20%);
  bottom: 0;
  right: 0.5em;
}

.init-popup-content {
  padding: 1.5em 1.25em 2.0em;
}

.init-popup-content .content-title {
  font-size: clamp(12px, 3.2vw, 28px);
  font-weight: 600;
  text-align: center;
}

.init-popup-content .btn-wrap {
  margin-top: 1.25em;
  display: grid;
  gap: 1em;
}

.init-popup-content .btn-wrap .btn {
  display: block;
  width: min(600px, 96%);
  background-color: #009dff;
  box-shadow: 0 6px #007dcc;
  color: #fff;
  padding: 1em;
  border-radius: 99px;
  cursor: pointer;
  margin-inline: auto;
  text-align: center;
  text-decoration: none !important;
  line-height: 1;
  transition: all 0.3s ease;
}

.init-popup-content .btn-wrap .btn:hover {
  box-shadow: 0 1px #007dcc;
  translate: 0 5px;
}

.init-popup-content .btn-wrap .text {
  font-size: 1.5em;
  font-weight: 600;
}

.init-popup-content .btn-wrap .caption {
  margin-top: 0.75em;
}


/* メディアクエリ //////////////////////////*/


