  }
}

@keyframes border-color {
  0% {
    border-color: #d02112;
  }

  50% {
    border-color: #eee;
  }

  100% {
    border-color: #d02112;
  }
}

@keyframes push {
  0% {
    margin-top: 0;
    margin-bottom: 10px;
    box-shadow: 0 10px 0 #aa5315;
  }

  50% {
    margin-top: 0;
    margin-bottom: 10px;
    box-shadow: 0 10px 0 #aa5315;
  }

  51% {
    margin-top: 10px;
