.curtain {
  width: 100%;
  position: relative;
  transition: 0.5s;
  overflow: hidden;
  min-height: 300px;
}

.curtain-left,
.curtain-right {
  position: absolute;
  top: -2em;
  width: 50%;
  height: calc(100% + 4em);
  background-color: rgb(177 0 0);
  pointer-events: none;
      background-image: linear-gradient(90deg, rgb(161 0 1) 30%, transparent 50%, rgb(135 0 1) 80%, transparent 100%);
  background-size: 4em;
  z-index: 1;
}

.curtain-left {
  left: 0;
  filter: drop-shadow(1px 6px 6px rgba(0, 0, 0, 0.319));
  box-shadow: 2px 0px 6px rgba(255, 255, 255, 0.24) inset, 0px 30px 25px rgba(0, 0, 0, 0.25) inset;
}

.curtain-right {
  right: 0;
  filter: drop-shadow(1px 6px 6px rgba(0, 0, 0, 0.319));
  box-shadow: 2px 0px 6px rgba(255, 255, 255, 0.24) inset, 0px 30px 25px rgba(0, 0, 0, 0.25) inset;
}

.curtain-content {
  position: relative;
  z-index: 0;
  opacity: 0;
  max-height: 0;
}

.curtain-btn {
  display: block;
  background-color: #00d6ca;
  padding: 0.75em 2em;
  width: fit-content;
  margin-inline: auto;
  margin-block: 1em;
  color: #FFF;
  font-weight: 600;
  border-radius: 0.25em;
  border-bottom: 4px solid #00b3a6;
}

.curtain-btn.is-clicked {
  display: none;
}

.curtain.is-ready .curtain-left {
  animation: is-ready-l 1s infinite;
}

.curtain.is-ready .curtain-right {
  animation: is-ready-r 1s infinite;
}

.curtain.is-open {
  animation: perpective 2s 2s forwards;
}

.curtain.is-open .curtain-left {
  animation: curtain-l 3s forwards;
}

.curtain.is-open .curtain-right {
  animation: curtain-r 3s forwards;
}

.curtain.is-open .curtain-content {
  animation: fadeIn 1s 2s forwards;
}

