@keyframes curtain-l {
  0% {
    visibility: visible;
  }

  20% {
    transform: rotate(0deg) translateX(0%);
  }

  60% {
    transform: rotate(6deg) translateX(-50%);
    background-size: 3em;
  }

  80% {
    opacity: 1;
  }

  100% {
    transform: rotate(0deg) translateX(-100%);
    opacity: 0;
    visibility: hidden;
    background-size: 2em;
  }
}

@keyframes curtain-r {
  0% {
    visibility: visible;
  }

  20% {
    transform: rotate(0deg) translateX(0%);
  }

  60% {
    transform: rotate(-6deg) translateX(50%);
    background-size: 3em;
  }

  80% {
    opacity: 1;
  }

  100% {
    transform: rotate(0deg) translateX(100%);
    opacity: 0;
    visibility: hidden;
    background-size: 2em;
  }
}

