}

.swiper {
  display: flex;
  margin-left: auto;
  margin-right: auto;
  position: relative;
  overflow: hidden;
  list-style: none;
  padding: 0;
  width: 100%;
  max-width: 800px;
  margin: 0 auto 20px;
}

.swiper-wrapper {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  transform: translate3d(0, 0, 0);
  transition-property: transform;
  box-sizing: content-box;
}

.swiper-slide {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-shrink: 0;
  width: 100%;
  height: auto;
  position: relative;
  transition-property: transform;
}

.swiper-slide img {
  vertical-align: bottom;
}

.swiper-slide img {
  width: 100%;
}

.swiper-slide img.lazyload:not(.loaded) {
  width: auto;
  max-width: 100%;
}

.swiper-button-next,
.swiper-button-prev {
  position: absolute;
  top: 50%;
  cursor: pointer;
}

.swiper-button-next {
  right: 10px;
  left: auto;
  outline: none;
}

.swiper-button-prev {
  left: 10px;
  right: auto;
  outline: none;
}

.swiper-button-next::before,
.swiper-button-prev::before {
  content: " ";
  width: 50px;
  height: 50px;
  position: absolute;
  z-index: 10;
}

.swiper-button-next::before {
  border-right: solid 8px #ccc;
  transform: translateY(-50%) rotate(45deg);
  right: 0;
}

.swiper-button-prev::before {
  border-left: solid 8px #ccc;
  transform: translateY(-50%) rotate(-45deg);
  left: 0;
}


.swiper-button-next::after,
.swiper-button-prev::after {
  content: " ";
  width: 50px;
  height: 50px;
  position: absolute;
  top: 5px;
  z-index: 10;
}

.swiper-button-next::after {
  border-right: solid 8px #ccc;
  transform: translateY(-54%) rotate(-45deg);
  right: 0;
}

.swiper-button-prev::after {
  border-left: solid 8px #ccc;
  transform: translateY(-54%) rotate(45deg);
  left: 0;
}

.swiper-button-next,
.swiper-button-prev {
  color: transparent !important;
}


