.swiper {
  display: flex;
  margin-left: auto;
  margin-right: auto;
  position: relative;
  overflow: hidden;
  list-style: none;
  width: 100%;
  max-width: 800px;
  margin: 0 auto 20px;
}

.swiper-wrapper {
  position: relative;
  width: 100%;
  height: auto;
  display: flex;
  transform: translate3d(0, 0, 0);
  transition-property: transform;
  box-sizing: content-box;
}

.swiper-slide {
  display: flex;
  justify-content: center;
  align-items: center;
}

.swiper-slide img {
  vertical-align: bottom;
}



