  width: auto;
  max-width: 100%;
}



.swiper-button-next,
.swiper-button-prev {
  position: absolute;
  top: 50%;
  cursor: pointer;
}



.swiper-button-next {
  right: 10px;
  left: auto;
  outline: none;
}



.swiper-button-prev {
  left: 10px;
  right: auto;
  outline: none;
}



.swiper-button-next::before,
.swiper-button-prev::before {
  content: " ";
  width: 50px;
  height: 50px;
  position: absolute;
  z-index: 10;
}



.swiper-button-next::before {
  border-right: solid 8px #ccc;
  transform: translateY(-50%) rotate(45deg);
  right: 0;
}



/*左側の矢印の棒（下）設定*/
.swiper-button-prev::before {
  border-left: solid 8px #ccc;
  transform: translateY(-50%) rotate(-45deg);
  left: 0;
}



.swiper-button-next::after,
.swiper-button-prev::after {
  content: " ";
  width: 50px;
  height: 50px;
  position: absolute;
  top: 5px;
  z-index: 10;
}



.swiper-button-next::after {
  border-right: solid 8px #ccc;
  transform: translateY(-54%) rotate(-45deg);
  right: 0;
}




.swiper-button-prev::after {
  border-left: solid 8px #ccc;
  transform: translateY(-54%) rotate(45deg);
  left: 0;
}

.swiper-button-next,
.swiper-button-prev {
  color: transparent !important;
}

.swiper-slide a {
  opacity: 1;
  transition: opacity 0.2s;
}

.swiper-slide a:hover {
  opacity: 0.8;
}

.acc-table {
  max-width: 400px;
  width: 100%;
  margin: 0 auto;
  border: 3px solid #ff1493;
  border-radius: 8px;
  box-shadow: rgba(0, 0, 0, 0.24) 0px 3px 8px;
  overflow: hidden;
}

.acc-table .acc-head {
  position: relative;
  font-size: 18px;
  color: #333333;
  font-weight: bold;
  line-height: 1.2;
  cursor: pointer;
  border-radius: 8px 8px 0 0;
  margin: -1px -1px 0;
  padding: 1em 2.2em 1em 1em;
}

.acc-table .acc-head::before,
.acc-table .acc-head::after {
  content: "";
  display: inline-block;
  width: 0.8em;
  height: 2px;
  background-color: #ff1493;
  position: absolute;
  top: calc(50%);
  right: 0.8em;
  -webkit-transform: none;
  transform: none;
}

.acc-table .acc-head::after {
  -webkit-transform: rotate(90deg);
  transform: rotate(90deg);
  transition: -webkit-transform 0.2s;
  transition: transform 0.2s;
  transition: transform 0.2s, -webkit-transform 0.2s;
}

.acc-table .acc-head.is-active::after {
  -webkit-transform: rotate(0);
  transform: rotate(0);
}

.acc-table .acc-head.is-active+.acc-body {
  height: auto;
  padding: 0 1em 1em;
  opacity: 1;
  visibility: visible;
}

.acc-table .acc-body {
  visibility: hidden;
  height: 0;
  opacity: 0;
  padding-top: 0;
  padding-bottom: 0;
  overflow: hidden;
  transition: padding-top 0.25s, padding-bottom 0.25s, opacity 0.25s, visibility 0.25s, height 0.25s;
}

