.swiper {
  display: flex;
  margin-left: auto;
  margin-right: auto;
  position: relative;
  overflow: hidden;
  list-style: none;
  /*余白なし*/
  padding: 0;
  /*スライドの横幅*/
  width: 100%;
  /* スライドの最大幅 */
  max-width: 800px;
  margin: 0 auto 20px;
}

.swiper-wrapper {
  position: relative;
  /*横幅*/
  width: 100%;
  /*高さ*/
  height: 100%;
  display: flex;
  transform: translate3d(0, 0, 0);
  transition-property: transform;
  box-sizing: content-box;
}

.swiper-slide {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-shrink: 0;
  width: 100%;
  height: auto;
  position: relative;
  transition-property: transform;
}

.swiper-slide img {
  vertical-align: bottom;
}

/*スライダー内の画像の設定*/
.swiper-slide img {
  /*横幅*/
  width: 100%;
}

.swiper-slide img.lazyload:not(.loaded) {
  width: auto;
  max-width: 100%;
}

/*矢印の設定*/
.swiper-button-next,
.swiper-button-prev {
  position: absolute;
  /*縦方向の位置（上起点）*/
  top: 50%;
  cursor: pointer;
}

/*右側の矢印の設定*/
.swiper-button-next {
  /*横方向の位置（右起点）*/
  right: 10px;
  left: auto;
  /*選択時のアウトラインの設定（非表示）*/
  outline: none;
}

/*左側の矢印の設定*/
.swiper-button-prev {
  /*横方向の位置（左起点）*/
  left: 10px;
  right: auto;
  /*選択時のアウトラインの設定（非表示）*/
  outline: none;
}

/*矢印の棒（下）の設定*/
.swiper-button-next::before,
.swiper-button-prev::before {
  content: " ";
  /*棒の横幅*/
  width: 50px;
  /*棒の高さ*/
  height: 50px;
  position: absolute;
  z-index: 10;
}

/*右側の矢印の棒（下）設定*/
.swiper-button-next::before {
  /*左から線種、太さ、色*/
  border-right: solid 8px #ccc;
  /*傾き（角度）*/
  transform: translateY(-50%) rotate(45deg);
  right: 0;
}

/*左側の矢印の棒（下）設定*/
.swiper-button-prev::before {
  /*左から線種、太さ、色*/
  border-left: solid 8px #ccc;
  /*傾き（角度）*/
  transform: translateY(-50%) rotate(-45deg);
  left: 0;
}

/*矢印の棒（上）の設定*/
.swiper-button-next::after,
.swiper-button-prev::after {
  content: " ";
  /*棒の横幅*/
  width: 50px;
  /*棒の高さ*/
  height: 50px;
  position: absolute;
