  border-right: solid 8px #ccc;
  transform: translateY(-54%) rotate(-45deg);
  right: 0;
}

.swiper-button-prev::after {
  border-left: solid 8px #ccc;
  transform: translateY(-54%) rotate(45deg);
  left: 0;
}

 .btnVisible__area {
  width: 100%;
  height: auto;
  position: relative;
}

 .btnVisible__area .btn {
  width: 100%;
  height: auto;
  border: none;
  background: none;
  cursor: pointer;
  animation-name: slideBtn;
  animation-duration: 1s;
  animation-iteration-count: infinite;
}

 .btnVisible__area .btn img {
  width: 100%;
  height: auto;
}

 .contents {
  width: 100%;
  height: auto;
  margin-top: 50px;
  position: relative;
}

 .contents .text {
  font-size: 1em;
}

 .contents .text._center {
  text-align: center;
}

 .contents img {
  width: 100%;
  height: auto;
}

 .is-hidden {
  display: none;
}

 .is-visible {
  display: block;
  position: relative;
  overflow-x: hidden;
}

 .is-visible:after {
  content: '';
  width: 100%;
  height: 100% !important;
  background: #fff;
  position: absolute;
  top: 0;
  left: 0;
  animation-name: bgSlide;
  animation-duration: 0.5s;
  animation-timing-function: 1;
  animation-fill-mode: forwards;
}

@keyframes slideBtn {
  0% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(20px);
  }

  100% {
    transform: translateY(0);
  }
}

@keyframes bgSlide {
  0% {
    transform: translateX(0);
  }

  100% {
    transform: translateX(100%);
  }
}

.arrowFlow__area {
  width: 100%;
  height: auto;
}

.arrowFlow__inner {
  padding-bottom: 200px;
  overflow-y: hidden;
  position: relative;
}

.arrowFlow__beforeG,
.arrowFlow__afterG {
  width: 80%;
  max-width: 400px;
  height: auto;
  margin: 0 auto;
  display: flex;
  justify-content: space-evenly;
  align-items: flex-start;
  animation-name: arrowFlow;
  animation-duration: 2s;
  animation-timing-function: ease-in-out;
  animation-iteration-count: infinite;
  transform: translate(-50%, -300%);
  position: absolute;
  top: 0;
  left: 50%;
}

.arrowFlow__afterG {
  animation-delay: 1s;
}

.arrow {
  display: inline-block;
  vertical-align: middle;
  color: #ba0d0d;
  line-height: 1;
  position: relative;
  width: 40px;
  height: 60px!important;
  background: currentColor;
  margin: 0 30px;
}

.arrow:before {
  content: "";
  display: inline-block;
  width: 0;
  height: 0;
  border-style: solid;
  border-width: 50px 50px 0 50px;
  border-color: #ba0d0d transparent transparent transparent;
  position: absolute;
  bottom: -50px;
  left: 50%;
  transform: translateX(-50%);
}

@keyframes arrowFlow {
  0% {
    transform: translate(-50%, -300%);
  }

  60% {
    transform: translate(-50%, 100%);
  }

  100% {
    transform: translate(-50%, 400%);
  }
}

.zoom {
  transform: scale(0, 0);
}

.is-zoomIn {
  animation: zoomIn 0.5s ease-in-out forwards;
  animation-delay: 0.5s;
}

@keyframes zoomIn {
  0% {
    transform: scale(0.5, 0.5);
  }

  100% {
    transform: scale(1, 1);
  }
}

