.spin-roulette {
  /* 最大幅 */
  max-width: 800px;
  width: 100%;
  margin: 0 auto;
  padding: 20px;
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
}

.spin-roulette .wrap-wheel {
  position: relative;
  top: 20px;
  left: 20px;
  width: 348px;
  max-width: unset;
  margin: 0 auto;
  border: 20px solid transparent;
  /* 外枠の背景色 */
  background: linear-gradient(0deg, #B67B03 0%, #DAAF08 45%, #FEE9A0 70%, #DAAF08 85%, #B67B03 90% 100%);
  border-radius: 50%;
  box-shadow: rgba(0, 0, 0, 0.24) 0px 3px 8px;
  background-clip: border-box;
  box-sizing: border-box;
  transform-origin: left top;
}

.spin-roulette .wrap-wheel::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  margin: auto;
  width: 120px;
  height: 120px;
  border: 10px solid transparent;
  /* 内枠の背景色 */
  background: linear-gradient(0deg, #B67B03 0%, #DAAF08 45%, #FEE9A0 70%, #DAAF08 85%, #B67B03 90% 100%);
  border-radius: 50%;
  box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
  background-clip: border-box;
  box-sizing: border-box;
  z-index: 5;
}

.spin-roulette .wrap-wheel .arrow {
  position: absolute;
  top: -25px;
  left: calc(50% - 25px);
  width: 50px;
  height: 60px;
  overflow: hidden;
  z-index: 10;
}

.spin-roulette .wrap-wheel .arrow::before {
  content: "";
  position: absolute;
  bottom: 30px;
  width: 50px;
  height: 50px;
  /* ピンの背景色 */
  background: linear-gradient(135deg, #cedbe9 0%, #aac5de 17%, #6199c7 50%, #3a84c3 51%, #419ad6 59%, #4bb8f0 71%, #3a8bc2 84%, #26558b 100%);
  transform: rotate(45deg) skew(25deg, 25deg);
}

.spin-roulette .wrap-wheel .btn-stop {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  margin: auto;
  width: 100px;
  height: 100px;
  border: none;
  border-radius: 50%;
  z-index: 10;
  cursor: pointer;
  animation: 2s linear 0.5s infinite alternate movebtn;
  /* STOPボタンテキストサイズ */
  font-size: 22px;
  /* STOPボタンテキスト色 */
  color: #ffffff;
  line-height: 100px;
  text-decoration: none;
  /* STOPボタン背景色 */
  background: #EB261E;
  text-align: center;
  overflow: hidden;
  /* STOPボタン光沢 */
  box-shadow: inset 0px 3px 0 rgba(255, 255, 255, 0.3), 0 3px 3px rgba(0, 0, 0, 0.3);
  font-weight: bold;
  /* STOPボタン影 */
  border-bottom: solid 3px #b32525;
  transition: transform 0.4s;
}

.spin-roulette .wrap-wheel .btn-stop:hover,
.spin-roulette .wrap-wheel .btn-stop:active {
  transform: scale(1.1);
  animation: none;
}

.spin-roulette .wrap-wheel .roulette-wheel {
  position: relative;
  width: 100%;
  padding: 100% 0 0;
  overflow: hidden;
  list-style: none;
  margin: 0;
  border-radius: 50%;
  box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
  animation-timing-function: linear;
  animation-duration: 1s;
  animation-fill-mode: forwards;
  animation-iteration-count: infinite;
  animation-name: spin;
}

.spin-roulette .wrap-wheel .roulette-wheel.stop {
  animation-timing-function: cubic-bezier(0.2, 0.4, 0.4, 1.04);
  animation-duration: 4.5s;
  animation-fill-mode: forwards;
  animation-iteration-count: 1;
}

.spin-roulette .wrap-wheel .roulette-wheel>li {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  margin: auto;
  width: 100px;
  height: 154px;
  transform-origin: 50px 154px;
  background: transparent;
  text-align: center;
  box-sizing: border-box;
}

.spin-roulette .wrap-wheel .roulette-wheel>li::before {
  content: "";
  top: 0;
  left: 0;
  position: absolute;
  display: inline-block;
  width: 0;
  height: 0;
  margin: 0;
  border-style: solid;
  border-width: 154px 50px;
  z-index: 0;
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(1) {
  transform: rotate(36deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(2) {
  transform: rotate(72deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(3) {
  transform: rotate(108deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(4) {
  transform: rotate(144deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(5) {
  transform: rotate(180deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(6) {
  transform: rotate(216deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(7) {
  -webkit-transform: rotate(252deg);
  transform: rotate(252deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(8) {
  transform: rotate(288deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(9) {
  transform: rotate(324deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(10) {
  transform: rotate(360deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li.red::before {
  /* ルーセット内赤セル背景色 */
  border-color: #c60000 transparent transparent;
}

.spin-roulette .wrap-wheel .roulette-wheel>li.red::after {
  /* ルーレット内赤セル文言 */
  content: "あたり";
  position: absolute;
  top: 10px;
  left: 50%;
  line-height: 0;
  /* ルーレット内赤セル文字サイズ */
  font-size: 18px;
  /* ルーレット内赤セル文字色 */
  color: #ffffff;
  font-weight: 700;
  writing-mode: vertical-rl;
  text-align: center;
}

.spin-roulette .wrap-wheel .roulette-wheel>li.blue::before {
  /* ルーレット内青セル背景色 */
  border-color: #0c003e transparent transparent;
}

.spin-roulette .wrap-wheel .roulette-wheel>li.blue::after {
  /* ルーレット内青セル文言 */
  content: "はずれ";
  position: absolute;
  top: 10px;
  left: 50%;
  line-height: 0;
  /* ルーレット内青セル文字サイズ */
  font-size: 18px;
  /* ルーレット内青セル文字色 */
  color: #ffffff;
  font-weight: 700;
  writing-mode: vertical-rl;
  text-align: center;
}

.wrap-result {
  /* 結果表示の最大幅 */
  max-width: 800px;
  width: 100%;
  margin: 0 auto;
  padding: 0;
  text-align: center;
  transition: max-height 0.5s;
  border-radius: 8px;
  position: relative;
  overflow: hidden;
  /* 下記max-heightをautoに変更すると結果表示部分がプレビューに表示されます。
  使用の際は0にしてください。 */
  max-height: 0;
}

.wrap-result .inner {
  padding: 10px 10px 1.5em;
}

@keyframes movebtn {
  0% {
    transform: scale(1);
  }

  40% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.1);
  }

  60% {
    transform: scale(1);
  }

  100% {
    transform: scale(1);
  }
}

@keyframes spin {
  from {
    transform: rotate(0);
  }

  to {
    transform: rotate(360deg);
  }
}

/* widget全体 */
.visibleChange__area {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  /* 外側の余白｜上下余白｜左右余白（センタリング）｜ */
  margin: 0 auto;
}



/* 最初に表示されてる箱 */
.visibleChange__area .firstContent {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* ボタン */
.visibleChange__area .firstContent .btn {
  /* 外側の余白｜上下余白｜左右余白（センタリング）｜ */
  margin: 0 auto;
  display: block;
}


/* ボタンを画像にする場合は以下のコメントアウトを外してご利用ください（ボタンの背景、線が無くなり、ボタンの画像が領域内に収まります） */
/* .visibleChange__area .firstContent .btn{
      border: none;
      background: none;
    } 

    .visibleChange__area .firstContent .btn img{
      width: 100%;
    }  */

/* ボタン押下後、表示される箱 */
.visibleChange__area .nextContent {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
}



/* 非表示にするクラス */
.is-hidden {
  /* 非表示 */
  display: none;
  /* 透明度 */
  opacity: 0;
  /* アニメーションの速さ */
  transition-duration: 100ms;
  /* アニメーションの対象 */
  transition-property: opacity;
}



/* フェードインするクラス */
.is-fadeIn {
  /* 透明度 */
  opacity: 1;
  /* アニメーションの速さ */
  transition-duration: 100ms;
  /* アニメーションの対象 */
  transition-property: opacity;
}



/* フェードアウトするクラス */
.is-fadeOut {
  /* 透明度 */
  opacity: 0;
  /* アニメーションの速さ */
  transition-duration: 100ms;
  /* アニメーションの対象 */
  transition-property: opacity;
}



/*画像を使用する場合*/
.visibleChange__area img {
  max-width: unset;
  /*画像横幅*/
  width: 100%;
  /*周りの余白｜上下｜左右（autoは真ん中寄せ）*/
  margin: 0 auto;
}

/* ウィジェット全体 */
.l-carousel_with_bg {
  /* 横幅 */
  width: 960px;
  /* 最大幅 */
  max-width: 100%;
  /* 外側余白|上|左右auto=自動|下| */
  margin: 0 auto 20px;
  /* 内側余白|上|左右|下| */
  padding: 4% 0;
  position: relative;
}

/* 背景 */
.l-carousel_with_bg__bg {
  /* 横幅 */
  width: 100%;
  /* 縦幅 */
  height: 100%;
  /* 左からの距離 */
  left: 0;
  /* 上からの距離 */
  top: 0;
  /* 外側余白 */
  margin: 0;
  /* 内側余白 */
  padding: 0;
  position: absolute;
  list-style-type: none;
}

/* 背景それぞれ */
.l-carousel_with_bg__bg__item {
  /* 横幅 */
  width: 100%;
  /* 縦幅 */
  height: 100%;
  /* 左からの距離 */
  left: 0;
  /* 上からの距離 */
  top: 0;
  /* 透明 */
  opacity: 0;
  /* 変化の仕方|透明度|かかる秒数| */
  transition: opacity 1s ease-in-out;
  z-index: 0;
  position: absolute;
}

.l-carousel_with_bg__bg__item.active {
  z-index: 1;
  opacity: 1;
}

.l-carousel_with_bg__bg__item img {
  width: 100%;
  height: 100% !important;
  object-fit: cover;
}

/* 背景の白い部分 */
.l-carousel_with_bg_whitearea {
  /* 横幅 */
  width: 24%;
  /* 縦幅 */
  height: 80%;
  /* 上からの距離 */
  top: 10%;
  /* 左からの距離 */
  left: 0%;
  /* 右からの距離 */
  right: 0%;
  /* 外側余白|auto=自動 */
  margin: auto;
  /* 色 */
  background-color: rgba(255, 255, 255, 0.6);
  z-index: 1;
  position: absolute;
}

/* カルーセル部分全体 */
.l-carousel_with_bg__slides {
  /* 最大幅 */
  max-width: 100%;
  /* 外側余白|上下|左右auto=自動| */
  margin: 0 auto;
  /* 内側余白|上下左右| */
  padding: 0;
  z-index: 2;
  position: relative;
}

.l-carousel_with_bg__slides .swiper {
  /* 横幅 */
  width: 100%;
  /* 内側余白|上|左右|下| */
  padding: 0;
  /* 外側余白|左auto=自動| */
  margin-left: auto;
  /* 外側余白|右auto=自動| */
  margin-right: auto;
  position: relative;
  overflow: hidden;
  list-style: none;
  z-index: 1;
  touch-action: pan-y;
  box-sizing: border-box;
}

.l-carousel_with_bg__slides .swiper .swiper-wrapper {
  transform: translate3d(0px, 0, 0);
  position: relative;
  width: 100%;
  height: 100%;
  z-index: 1;
  display: flex;
  transition-property: transform;
  box-sizing: content-box;
  transition-timing-function: ease-in-out;
}

.l-carousel_with_bg__slides .swiper .swiper-slide {
  overflow: hidden;
  flex-shrink: 0;
  width: 100%;
  height: 100%;
  position: relative;
  transition-property: transform;
  box-sizing: border-box;
}

.l-carousel_with_bg__slides .swiper .swiper-slide .wrap-img {
  margin: 0;
  padding: 0;
}

.l-carousel_with_bg__slides .swiper .swiper-slide .wrap-img>img {
  max-width: 100%;
  width: 100%;
  vertical-align: middle;
}

/* スマホ(画面幅640px以下)の場合の設定 */
@media screen and (max-width: 640px) {
  .l-carousel_with_bg {
    width: 100%;
    padding: 10% 0;
  }

  .l-carousel_with_bg_whitearea {
    width: 54%;
  }
}

