.swiper-button-next,
.swiper-button-prev {
  position: absolute;
  /*進む、戻るボタンの縦位置*/
  top: 50%;
  z-index: 10;
  cursor: pointer;
}

.swiper-button-next {
  /*進むボタンの横位置（初期：画面右基準）*/
  right: 20px;
  left: auto;
  outline: none;
}

.swiper-button-prev {
  /*戻るボタンの横位置（初期：画面左基準）*/
  left: 20px;
  right: auto;
  outline: none;
}

.swiper-button-next::before,
.swiper-button-prev::before {
  content: " ";
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background-color: #e3e3e3;
  opacity: 0.6;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
}

.swiper-button-next::before {
  /*進むボタンの丸*/
  /* border-right: solid 5px #ccc;
 transform: translatey(-50%) rotate(35deg); */
  right: 0;
}

.swiper-button-prev::before {
  /*戻るボタンの丸*/
  left: 0;
}

.swiper-button-next::after,
.swiper-button-prev::after {
  content: " ";
  width: 5px;
  height: 5px;
  position: absolute;
  top: 50%;
  margin-top: -4.5px;
}

.swiper-button-next::after {
  /*進むボタンの線種、線の太さ、線の色*/
  right: 7px;
  border-top: 2px solid #767676;
  border-right: 2px solid #767676;
  -webkit-transform: rotate(45deg);
  transform: rotate(45deg);
}

.swiper-button-prev::after {
  /*戻るボタンの線種、線の太さ、線の色*/
  left: 7px;
  border-top: 2px solid #767676;
  border-left: 2px solid #767676;
  -webkit-transform: rotate(-45deg);
  transform: rotate(-45deg);
}

