  border-radius: 50%;
  box-shadow: rgba(0, 0, 0, 0.24) 0px 3px 8px;
  background-clip: border-box;
  box-sizing: border-box;
  transform-origin: left top;
}

.spin-roulette .wrap-wheel::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  margin: auto;
  width: 120px;
  height: 120px;
  border: 10px solid transparent;
  /* 内枠の背景色 */
  background: linear-gradient(0deg, #B67B03 0%, #DAAF08 45%, #FEE9A0 70%, #DAAF08 85%, #B67B03 90% 100%);
  border-radius: 50%;
  box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
  background-clip: border-box;
  box-sizing: border-box;
  z-index: 5;
}

.spin-roulette .wrap-wheel .arrow {
  position: absolute;
  top: -25px;
  left: calc(50% - 25px);
  width: 50px;
  height: 60px;
  overflow: hidden;
  z-index: 10;
}

.spin-roulette .wrap-wheel .arrow::before {
  content: "";
  position: absolute;
  bottom: 30px;
  width: 50px;
  height: 50px;
  /* ピンの背景色 */
  background: linear-gradient(135deg, #cedbe9 0%, #aac5de 17%, #6199c7 50%, #3a84c3 51%, #419ad6 59%, #4bb8f0 71%, #3a8bc2 84%, #26558b 100%);
  transform: rotate(45deg) skew(25deg, 25deg);
}

.spin-roulette .wrap-wheel .btn-stop {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  margin: auto;
  width: 100px;
  height: 100px;
  border: none;
  border-radius: 50%;
  z-index: 10;
  cursor: pointer;
  -webkit-animation: 2s linear 0.5s infinite alternate movebtn;
  animation: 2s linear 0.5s infinite alternate movebtn;
  /* STOPボタンテキストサイズ */
  font-size: 17px;
  /* STOPボタンテキスト色 */
  color: #ffffff;
  line-height: 100px;
  text-decoration: none;
  /* STOPボタン背景色 */
  background: #EB261E;
  text-align: center;
  overflow: hidden;
  /* STOPボタン光沢 */
  box-shadow: inset 0px 3px 0 rgba(255, 255, 255, 0.3), 0 3px 3px rgba(0, 0, 0, 0.3);
  font-weight: bold;
  /* STOPボタン影 */
  border-bottom: solid 3px #b32525;
  transition: transform 0.4s;
}

.spin-roulette .wrap-wheel .btn-stop:hover,
.spin-roulette .wrap-wheel .btn-stop:active {
  transform: scale(1.1);
  animation: none;
}

.spin-roulette .wrap-wheel .roulette-wheel {
  position: relative;
  width: 100%;
  padding: 100% 0 0;
  overflow: hidden;
  list-style: none;
  margin: 0;
  border-radius: 50%;
  box-shadow: rgba(0, 0, 0, 0.35) 0px 5px 15px;
  animation-timing-function: linear;
  animation-duration: 1s;
  animation-fill-mode: forwards;
  animation-iteration-count: infinite;
  animation-name: spin;
}

.spin-roulette .wrap-wheel .roulette-wheel.stop {
  animation-timing-function: cubic-bezier(0.2, 0.4, 0.4, 1.04);
  animation-duration: 4.5s;
  animation-fill-mode: forwards;
  animation-iteration-count: 1;
  animation-name: finish;
}

.spin-roulette .wrap-wheel .roulette-wheel>li {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  margin: auto;
  width: 100px;
  height: 154px;
  transform-origin: 50px 154px;
  background: transparent;
  text-align: center;
  box-sizing: border-box;
}

.spin-roulette .wrap-wheel .roulette-wheel>li::before {
  content: "";
  top: 0;
  left: 0;
  position: absolute;
  display: inline-block;
  width: 0;
  height: 0;
  margin: 0;
  border-style: solid;
  border-width: 154px 50px;
  z-index: 0;
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(1) {
  transform: rotate(36deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(2) {
  transform: rotate(72deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(3) {
  transform: rotate(108deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(4) {
  transform: rotate(144deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(5) {
  transform: rotate(180deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(6) {
  transform: rotate(216deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(7) {
  transform: rotate(252deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(8) {
  transform: rotate(288deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(9) {
  transform: rotate(324deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li:nth-child(10) {
  transform: rotate(360deg);
}

.spin-roulette .wrap-wheel .roulette-wheel>li.red::before {
  /* ルーセット内赤セル背景色 */
  border-color: #c60000 transparent transparent;
}

.spin-roulette .wrap-wheel .roulette-wheel>li.red::after {
  /* ルーレット内赤セル文言 */
  content: "あたり";
  position: absolute;
  top: 10px;
  left: 50%;
  line-height: 0;
  /* ルーレット内赤セル文字サイズ */
  font-size: 18px;
  /* ルーレット内赤セル文字色 */
  color: #ffffff;
  font-weight: 700;
  writing-mode: vertical-rl;
  text-align: center;
}

.spin-roulette .wrap-wheel .roulette-wheel>li.blue::before {
  /* ルーレット内青セル背景色 */
  border-color: #0c003e transparent transparent;
}

.spin-roulette .wrap-wheel .roulette-wheel>li.blue::after {
  /* ルーレット内青セル文言 */
  content: "はずれ";
  position: absolute;
  top: 10px;
  left: 50%;
  line-height: 0;
  /* ルーレット内青セル文字サイズ */
  font-size: 18px;
  /* ルーレット内青セル文字色 */
  color: #ffffff;
  font-weight: 700;
  writing-mode: vertical-rl;
  text-align: center;
}

@keyframes movebtn {
  0% {
    transform: scale(1);
  }

  40% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.1);
  }

  60% {
    transform: scale(1);
  }

  100% {
    transform: scale(1);
  }
}

@keyframes spin {
  from {
    transform: rotate(0);
  }

  to {
    transform: rotate(360deg);
  }
}

/* 全体の設定 */
.popupContent {
  position: relative;
}



/* バナーなどのエリア設定 */
.bnr__area {
  /* 横幅 */
  width: 500px;
  /* 最大幅 */
  max-width: 100%;
  /* 高さ */
  height: auto;
  /*外側の余白｜上下余白｜左右余白（auto=センタリング）｜*/
  margin: 0 auto;
}



/* ポップアップのトリガー部分 */
.bnr__area label input[type="checkbox"] {
  /* 非表示 */
  display: none;
}



/* バナーなど */
.bnr__area label img {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: auto;
  /* 表示順番 */
  z-index: 1;
}



/* ポップアップ（初期非表示） */
.popup__area {
  /* 画面全体の背景色 */
  background: rgba(0, 0, 0, 0.6);
  position: absolute;
  /* 横幅 */
  width: 100vw;
  /* 高さ */
  height: 100vh;
  /* 最大幅 */
  max-width: none;
  /*外側の余白｜上下余白｜左右余白｜*/
  margin: 0 calc(50% - 50vw);
  /* 表示位置（上基準） */
  top: -15px;
  /* 表示位置（左基準） */
  left: 0;
  /* 非表示 */
  display: none;
  box-sizing: border-box;
  /* 表示順番 */
  z-index: 10;
}



/* ポップアップ（背景白部分） */
.popup__box {
  /* 横幅 */
  width: 60%;
  /* 高さ */
  height: 80%;
  /* 最大幅 */
  max-width: 600px;
  /* 背景色 */
  background: #fff;
  /*内側の余白｜上下余白｜左右余白｜*/
  padding: 30px 40px;
  position: absolute;
  /* 表示位置（上基準） */
  top: 50%;
  /* 表示位置（下基準） */
  left: 50%;
  /* 表示位置調整（垂直方向, 水平方向） */
  transform: translate(-50%, -50%);
  /* はみ出た部分はスクロールする */
  overflow-y: scroll;
}



/* ポップアップの中身 */
.popup__contents {
  /* 横幅 */
  width: calc(100% - 40px);
  /* 高さ */
  height: auto;
  /* 線｜太さ｜線種｜色｜ */
  border: 1px solid #ccc;
  /* 外側の上余白 */
  margin-top: 20px;
  /* 内側の上下左右余白 */
  padding: 20px;
}



/* ポップアップ内コンテンツの一番初めのエリア */
.popup__contents:first-of-type {
  /* 外側の上余白 */
  margin-top: 0;
}



/* 見出し */
.popup__contents .head {
  /* 文字の大崎 */
  font-size: 1.25rem;
  /* 文字の色 */
  color: #555;
  /* 下線｜太さ｜線種｜色｜ */
  border-bottom: 1px solid #ccc;
  /* 内側の下余白 */
  padding-bottom: 16px;
}



/* テキスト */
.popup__contents .text {
  /* 文字の大きさ */
  font-size: 1rem;
  /* 文字の色 */
  color: #555;
  /* 上側の余白 */
  margin-top: 1rem;
}



/* リンクがある場合 */
.popup__contents a {
  /* 文字の色 */
  color: #0000ff;
  /* 下線 */
  text-decoration: underline;
}



/* リンクホバー時 */
.popup__contents a:hover {
  /* 下線 */
  text-decoration: none;
}



/* ポップアップの閉じるボタン */
.closeBtn {
  position: absolute;
  /* 表示位置（上基準） */
  top: 2px;
  /* 表示位置（右基準） */
  right: 7px;
}



/* 閉じるボタンの詳細（初期化） */
.closeBtn .btn {
  /* 線（なし） */
  border: none;
  /* 背景色（なし） */
  background: none;
  position: relative;
  /* 横幅 */
  width: 30px;
  /* 高さ */
  height: 30px;
}



/* 閉じるボタン（×の片方の線） */
.closeBtn .btn:before {
  content: '';
  /* 横幅 */
  width: 21px;
  /* 高さ */
  height: 4px;
  /* 線｜太さ｜線種｜色｜ */
  border-top: 4px solid #555;
  display: block;
  /* 回転 */
  transform: rotate(45deg);
  position: absolute;
  /* 表示位置（上基準） */
  top: 13px;
  /* 表示位置（右基準） */
  right: 2px;
}



/* 閉じるボタン（×の片方の線） */
.closeBtn .btn:after {
  content: '';
  /* 横幅 */
  width: 21px;
  /* 高さ */
  height: 4px;
  /* 線｜太さ｜線種｜色｜ */
  border-top: 4px solid #555;
  display: block;
  /* 回転 */
  transform: rotate(-45deg);
  position: absolute;
  /* 表示位置（上基準） */
  top: 13px;
  /* 表示位置（右基準） */
  right: 0;
}



/* ポップアップが開く時に付与されるクラス */
.is-open {
  /*アニメーションの設定｜アニメーション名｜1回のサイクルに要する時間｜進め方｜実行回数｜*/
  animation: openAnime 0.5s ease-in-out 1;
}



/* ポップアップが閉じる時に付与されるクラス */
.is-close {
  /*アニメーションの設定｜アニメーション名｜1回のサイクルに要する時間｜進め方｜実行回数｜*/
  animation: closeAnime 0.5s ease-in-out 1;
}

@keyframes openAnime {

  /* 始まり */
  0% {
    /* 透明度 */
    opacity: 0;
    /* 大きさ */
    transform: scale(1.3);
  }

  /* 終わり */
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes closeAnime {
  0% {
    opacity: 1;
    transform: scale(1);
  }

  100% {
    opacity: 0;
    transform: scale(1.3);
  }
}

