/*アニメーションの設定*/
.zoom {
  /*ズームさせる秒数（例：0.5秒）*/
  animation: zoomIn 0.5s ease-in-out forwards;
  /*画面が表示されてからの秒数（例：2秒後に実行）*/
  animation-delay: 2s;
  transform: scale(0, 0);
}

@keyframes zoomIn {
  0% {
    transform: scale(0.5, 0.5);
  }

  100% {
    transform: scale(1, 1);
  }
}

/* 全体設定 */
.sakura__box {
  /* 横幅 */
  width: 100%;
  /* 高さ */
  height: 500px;
  /* はみ出した要素の処理 */
  overflow: hidden;
  /* 背景（グラデーション：左側の色（上）→右側の色（下） */
  background: linear-gradient(#00bfff, #fff);
  position: relative;
}



/* テキスト部分の設定 */
.sakura__box .text {
  /* 横幅 */
  width: 90%;
  /* 文字の大きさ */
  font-size: 5rem;
  /* 文字色 */
  color: #fff;
  /* 文字の位置 */
  text-align: center;
  /* 外側の余白 */
  margin: 0;
  /* テキストのセンタリング設定 */
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}



/* 桜の設定 */
.sakura__box .sakura {
  position: absolute;
  /* 初期位置は領域より上-50pxの場所 */
  top: -50px;
  /* 桜の色 */
  background: #ffdbed;
  /* 角丸（桜の形） */
  border-radius: 0% 70%;
  /* 未設定の桜の動き [落ち方]｜keyframe fallを適用｜落ちるまでの時間｜落ち方｜落ちる回数｜
                   [動き方]｜keyframe sway1を適用｜1回分の動く時間｜動き方｜動く回数｜1回ごとに動きを反転｜ */
  animation: fall 4s linear infinite, sway1 2s ease-in-out infinite alternate;
}


@keyframes fall {
  to {
    top: 120%;
  }
}


@keyframes sway1 {
  from {
    transform: translateX(0px) rotate(0deg);
  }
  to {
    transform: translateX(200px) rotate(-45deg);
  }
}

@keyframes sway2 {
  from {
    transform: translateX(200px) rotate(-45deg);
  }
  to {
    transform: translateX(0px) rotate(0deg);
  }
}



/* 花弁ごとの動きの設定 */
