  /* 開始位置 */
  left: 0%;
  /* 桜の花弁の横幅 */
  width: 24px;
  /* 桜の花弁の高さ */
  height: 15px;
  /* 桜の動き [落ち方]｜keyframe fallを適用｜落ちるまでの時間｜落ち方｜落ちる回数｜
            [動き方]｜keyframe sway1を適用｜1回分の動く時間｜動き方｜動く回数｜1回ごとに動きを反転｜ */
  animation: fall 10s linear infinite,
