.tooltip-click .tooltip-txt {
  display: inline-block;
  position: relative;
  cursor: pointer;
}

.tooltip-click .tooltip-txt::before,
.tooltip-click .tooltip-txt::after {
  position: absolute;
  transition: all 0.2s;
  display: none;
  z-index: 2;
  box-sizing: border-box;
}

.tooltip-click .tooltip-txt::before {
  border: 8px solid transparent;
  border-color: #666666 transparent transparent transparent;
  content: "";
  height: 0;
  left: 50%;
  bottom: calc(100% - 7px);
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
  width: 0;
}

.tooltip-click .tooltip-txt::after {
  /* 文字サイズ */
  font-size: 12px;
  /* 文字色 */
  color: #fff;
  /* 背景色 */
  background: #666666;
  border-radius: 3px;
  content: attr(data-tooltip);
  padding: 5px 10px;
  bottom: calc(100% + 8px);
  left: 50%;
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
  white-space: pre;
}

.tooltip-click>input {
  display: none;
}

.tooltip-click>input:checked+.tooltip-txt::before,
.tooltip-click>input:checked+.tooltip-txt::after {
  display: inline-block;
}

.tooltip-hover {
  display: inline-block;
  position: relative;
}

.tooltip-hover::before,
.tooltip-hover::after {
  position: absolute;
  transition: all 0.2s;
  display: none;
  z-index: 2;
  box-sizing: border-box;
}

.tooltip-hover::before {
  border: 8px solid transparent;
  border-color: #666666 transparent transparent transparent;
  content: "";
  height: 0;
  left: 50%;
  bottom: calc(100% - 7px);
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
  width: 0;
}

.tooltip-hover::after {
  /* 文字サイズ */
  font-size: 12px;
  /* 文字色 */
  color: #fff;
  /* 背景色 */
  background: #666666;
  border-radius: 3px;
  content: attr(data-tooltip);
  padding: 5px 10px;
  bottom: calc(100% + 8px);
  left: 50%;
  -webkit-transform: translateX(-50%);
  transform: translateX(-50%);
  white-space: pre;
}

.tooltip-hover:hover {
  cursor: pointer;
}

.tooltip-hover:hover::before,
.tooltip-hover:hover::after {
  display: inline-block;
}

