.fixed-footer {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  width: 100%;
  z-index: 1000;
}

.fixed-footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-around;
}

img {
  display: flex;
  width: 90%;
  height: auto;
  margin: 0 auto !important;
}

.fixed-wrap {
  opacity: 1;
  transition: opacity 0.5s;
}

.fixed-wrap.hide {
  opacity: 0;
  pointer-events: none;
}

.swiper {
  display: flex;
  margin-left: auto;
  margin-right: auto;
  position: relative;
  overflow: hidden;
  list-style: none;
  padding: 0;
  z-index: 1;
  /*スライド全体の横幅*/
  width: 100%;
}

.swiper-wrapper {
  position: relative;
  width: 100%;
  height: 100%;
  z-index: 1;
  display: flex;
  transform: translate3d(0px, 0, 0);
  transition-property: transform;
  box-sizing: content-box;
}

.swiper-slide {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-shrink: 0;
  width: 100%;
  height: auto;
  position: relative;
  transition-property: transform;
}

.swiper-slide img {
  /*スライド内の画像の横幅*/
  width: 80%;
}

.swiper-slide img.lazyload:not(.loaded) {
  width: auto;
  max-width: 80%;
}

.swiper-button-next,
.swiper-button-prev {
  position: absolute;
  /*進む、戻るボタンの縦位置*/
  top: 50%;
  z-index: 10;
  cursor: pointer;
}

.swiper-button-next {
  /*進むボタンの横位置（初期：画面右基準）*/
  right: 20px;
  left: auto;
  outline: none;
}

.swiper-button-prev {
  /*戻るボタンの横位置（初期：画面左基準）*/
  left: 20px;
  right: auto;
  outline: none;
}

.swiper-button-next::before,
.swiper-button-prev::before {
  content: ' ';
  width: 30px;
  height: 30px;
  position: absolute;
  top: calc(50%);
}

.swiper-button-next::before {
  /*進むボタン（下）の線種、線の太さ、線の色*/
  border-right: solid 5px #ccc;
  transform: translatey(-50%) rotate(35deg);
  right: 10px;
}

.swiper-button-prev::before {
  /*戻るボタン（下）の線種、線の太さ、線の色*/
  border-left: solid 5px #ccc;
  transform: translatey(-50%) rotate(-35deg);
  left: 10px;
}

.swiper-button-next::after,
.swiper-button-prev::after {
  content: ' ';
  width: 30px;
  height: 30px;
  position: absolute;
  top: calc(50% - 5px);
}

.swiper-button-next::after {
  /*進むボタン（上）の線種、線の太さ、線の色*/
  border-right: solid 5px #ccc;
  transform: translatey(-50%) rotate(-35deg);
  right: 10px;
}

.swiper-button-prev::after {
  /*戻るボタン（上）の線種、線の太さ、線の色*/
  border-left: solid 5px #ccc;
  transform: translatey(-50%) rotate(35deg);
  left: 10px;
}

