/* 画像 */
.img {
  margin: 0 auto;
  max-width: 100%;
  height: auto;
}

.visible .img-bar {
  animation:
    swing .3s linear infinite alternate,
    slide-to-right 1s cubic-bezier(1, 0, 1, 0);
}

.visible .img-main {
  animation:
    slide-to-left 1s cubic-bezier(1, 0, 1, 0) 0.5s,
    fade-in 1s cubic-bezier(1, 0, 1, 0);
}

.img-btn {
  width: 60%;
}

.visible .img-btn {
  animation:
    fluffy .8s ease-in-out infinite alternate,
    slide-to-top 1s cubic-bezier(1, 0, 1, 0) 0.7s,
    fade-in 1.2s cubic-bezier(1, 0, 1, 0);
}

.img-arrow {
  transition: opacity 0s 4.2s;
  position: absolute;
  top: 0;
  left: 30%;
  width: 15%;
}

.visible .img-arrow {
  animation:
    side-ways .4s ease-in-out infinite alternate,
    fade-in 2.5s cubic-bezier(1, 0, 1, 0);
}

/* animation */
@keyframes swing {
  to {
    transform: rotate(-5deg)
  }
}

@keyframes fluffy {
  to {
    transform: scale(1.05)
  }
}

@keyframes side-ways {
  to {
    left: 10%;
  }
}

@keyframes slide-to-right {
  from {
    transform: translateX(-300px)
  }

  to {
    transform: translateX(0)
  }
}

@keyframes slide-to-left {
  from {
    transform: translateX(300px)
  }

  to {
    transform: translateX(0)
  }
}

@keyframes slide-to-top {
  from {
    transform: translateY(300px)
  }

  to {
    transform: translateY(0)
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}



/* jsで可変 */
.hidden {
  visibility: hidden;
}

.visible {
  visibility: visible;
  z-index: 1;
}



/* 閉じるボタン */
.close {
  position: absolute;
  display: inline-block;
  top: 0px;
  right: 0px;
  width: 32px;
  height: 32px;
  border: 0;
  background-color: black;
  border-radius: 32px;
  margin: 0;
  padding: 0;
  transform: scale(0.5);
  cursor: pointer;
  z-index: 100;
}

.close:before {
  content: "";
  position: absolute;
  display: inline-block;
  top: 4px;
  left: 13px;
  width: 6px;
  height: 24px;
  border: 0;
  margin: 0;
  padding: 0;
  background-color: white;
  transform: rotate(45deg);
}

.close:after {
  content: "";
  position: absolute;
  display: inline-block;
  top: 4px;
  left: 13px;
  width: 6px;
  height: 24px;
  border: 0;
  margin: 0;
  padding: 0;
  background-color: white;
  transform: rotate(-45deg);
}

.close:hover {
  background-color: red;
}

 .fadein {
  /*文字の大きさ*/
  font-size: 20px;
  /*文字の太さ*/
  font-weight: bold;
  /*アニメーションの名前*/
  animation-name: fadein;
  /*フェードインする時間*/
  animation-duration: 2s;
  /*アニメーションの回数（inifinite=無限、3=3回）*/
  animation-iteration-count: infinite;
}

/*アニメーションの設定*/
@keyframes fadein {
  from {
    opacity: 0;
    transform: translateY(20px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

 .purupuru {
  /*アニメーション名、動きの速さ0.8s（=0.8秒）、動き具合、開始時間5s(=5秒後)、動く回数infinite(=無限 3=3回など)   */
  animation: purupuru 0.8s linear 5s infinite;
}

@keyframes purupuru {
  0% {
    transform: skew(9deg);
  }

  10% {
    transform: skew(-8deg);
  }

  20% {
    transform: skew(7deg);
  }

  30% {
    transform: skew(-6deg);
  }

  40% {
    transform: skew(5deg);
  }

  50% {
    transform: skew(-4deg);
  }

  60% {
    transform: skew(3deg);
  }

  70% {
    transform: skew(-2deg);
  }

  80% {
    transform: skew(1deg);
  }

  90% {
    transform: skew(0deg);
  }
  100% {
    transform: skew(0deg);
  }
}

 .left-right {
  /*動きの速さ　2s=2秒*/
  animation-duration: 2s;
  /*動き具合*/
  animation-timing-function: ease-in;
  /*動く回数　infinite=無限, 3=3回*/
  animation-iteration-count: infinite;
  /*アニメーション名*/
  animation-name: both-way;
}

@keyframes both-way {
  0% {
    transform: translateX(-5px);
  }

  45% {
    transform: translateX(5px);
  }

  50% {
    transform: translateX(7px);
  }

  55% {
    transform: translateX(10px);
  }

  95% {
    transform: translateX(5px);
  }

  100% {
    transform: translateX(-5px);
  }
}

/*動きの速さを変更する場合は、複数あるanimation-durationの1.5s(=1.5秒)の時間を変更
動きの回数を変更する場合は、複数あるanimation-iteration-countのinfinite（=無限,   3=3回など）を変更*/
.movebtn {
  -webkit-animation-name: btnAnime02;
  -webkit-animation-duration: 1.5s;
  -webkit-animation-iteration-count: infinite;
  -webkit-animation-timing-function: ease;
  -moz-animation-name: btnAnime02;
  -moz-animation-duration: 1.5s;
  -moz-animation-iteration-count: infinite;
  -moz-animation-timing-function: ease;
  display: flex;
  align-items: flex-start;
  justify-content: center;
}

@-webkit-keyframes btnAnime02 {
  0% {
    -webkit-transform: translate(0, 0);
  }

  50% {
    -webkit-transform: translate(0, -8px);
  }

  100% {
    -webkit-transform: translate(0, 0);
  }
}

@-moz-keyframes btnAnime02 {
  0% {
    -moz-transform: translate(0, 0);
  }

  50% {
    -moz-transform: translate(0, -8px);
  }

  100% {
    -moz-transform: translate(0, 0);
  }
}

/*動きの速さをかえたいときは、 animationの1s(=1秒)の時間を変更 */
.flash {
  animation: flash 1s ease infinite alternate;
  display: flex;
  /*左寄せは flex-start、真ん中寄せはcenter*/
  justify-content: center;
}

/*設定した時間（初期：1秒）の半分の時に透明になる*/
@keyframes flash {
  50% {
    opacity: 0;
  }
}

/*動きの速さをかえたいときは、.swing内の5s(=5秒)の時間を変更 */
.swing {
  /*画像の外側の余白*/
  margin: 8px;
  /*アニメーション名、動き具合、動きの速さ5s（=5秒）、動きの回数infinite(=無限　3=3回など)
  動きの速さと回数を変更する場合は、2箇所ずつ変更してください*/
  -ms-animation: swing linear 5s infinite;
  animation: swing linear 5s infinite;
  /*変形の起点、1番目の値はX軸、2番目の値はY軸、3番目の値はZ軸
  起点を変更する場合は2箇所ずつ変更してください。*/
  -ms-transform-origin: center -24px 0;
  transform-origin: center -24px 0;
}


@-webkit-keyframes swing {
  0% {
    -webkit-transform: rotate(0deg);
  }

  25% {
    -webkit-transform: rotate(5deg);
  }

  50% {
    -webkit-transform: rotate(0deg);
  }

  75% {
    -webkit-transform: rotate(-5deg);
  }

  100% {
    -webkit-transform: rotate(0deg);
  }
}


@keyframes swing {
  0% {
    transform: rotate(0deg);
  }

  25% {
    transform: rotate(5deg);
  }

  50% {
    transform: rotate(0deg);
  }

  75% {
    transform: rotate(-5deg);
  }

  100% {
    transform: rotate(0deg);
  }
}

ul {
  /* 全体の中央寄せ */
  text-align: center;
  margin: 0;
  padding: 0;
  list-style: none;
}


/*ボタンを囲っているBoxの設定*/
.fuwafuwa_btnBox {
  display: inline-block;
  /*外側の余白、上下左右20pxずつ*/
  margin: 20px;
}


/*ボタン部分の設定*/
.fuwafuwa_link {
  display: flex;
  justify-content: center;
  align-items: center;
  /*下線などの装飾*/
  text-decoration: none;
  /*文字位置*/
  text-align: center;
  /*最大幅*/
  max-width: 100%;
  /*外側の余白、上下左右20pxずつ*/
  padding: 20px;
  /*角丸*/
  border-radius: 50%;
  /*背景の色*/
  background: #666;
  /*文字の色*/
  color: #fff;
  /*Y軸アニメーションの設定
 アニメーション名、動きの速さ1s（=1秒）、動き具合、動く回数infinite(=無限)、動きの向き*/
  animation: vertical 1s ease-in-out infinite alternate;
}

.fuwafuwa_link::before {
  display: block;
  content: '';
  padding-top: 100%;
}


/*奇数番目の要素の設定（X軸）*/
.fuwafuwa_btnBox:nth-child(odd) {
  /*アニメーション名、動きの速さ1s（=1秒）、動き具合、動く回数infinite(=無限)、動きの向き*/
  animation: horizontal1 1s ease-in-out infinite alternate;
}


/*偶数番目の要素の設定（X軸）*/
.fuwafuwa_btnBox:nth-child(even) {
  /*アニメーション名、動きの速さ1s（=1秒）、動き具合、動く回数infinite(=無限)、動きの向き*/
  animation: horizontal2 1s ease-in-out infinite alternate;
}


/*Y軸アニメーションが完了するまでの時間*/
/*1,            4,            7,            10...番目*/
.fuwafuwa_btnBox:nth-child(3n+1) .fuwafuwa_link {
  animation-duration: 1.1s;
}



/*2,            5,            8,            11...番目*/
.fuwafuwa_btnBox:nth-child(3n+2) .fuwafuwa_link {
  animation-duration: 1.3s;
}



/*3,            6,            9,            12...番目*/
.fuwafuwa_btnBox:nth-child(3n+3) .fuwafuwa_link {
  animation-duration: 1.5s;
}

@-webkit-keyframes horizontal1 {
  0% {
    transform: translateX(-3px);
  }

  100% {
    transform: translateX(0px);
  }
}

@-webkit-keyframes horizontal2 {
  0% {
    transform: translateX(3px);
  }

  100% {
    transform: translateX(0px);
  }
}

@-webkit-keyframes vertical {
  0% {
    transform: translateY(-10px);
  }

  100% {
    transform: translateY(0px);
  }
}

.buruburu {
  display: inline-block;
  animation: hurueru .1s infinite;
}

@keyframes hurueru {
  0% {
    transform: translate(0px, 0px) rotateZ(0deg);
  }

  25% {
    transform: translate(2px, 2px) rotateZ(1deg);
  }

  50% {
    transform: translate(0px, 2px) rotateZ(0deg);
  }

  75% {
    transform: translate(2px, 0px) rotateZ(-1deg);
  }

  100% {
    transform: translate(0px, 0px) rotateZ(0deg);
  }
}
